{
  "title": "The Rescue of Ashvale",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A small band gathers at dawn before the ruined city.",
      "visual_description": "Four travelers crest a hill of broken stones, looking down at a shattered skyline of toppled spires and smoke. Pale dawn light, banners of a fallen kingdom flapping in the distance.",
      "characters": ["map_reader", "scout", "magic_helper", "bridge_walker"]
    },
    {
      "scene_number": 2,
      "caption": "The map reader traces the safest path inward.",
      "visual_description": "Close shot of weathered hands smoothing a torn map over a flat stone, marking the castle keep with a charcoal X. Wind tugs at the parchment.",
      "characters": ["map_reader", "scout"]
    },
    {
      "scene_number": 3,
      "caption": "They approach the great castle gates.",
      "visual_description": "Massive iron-bound gates hang half off their hinges, carved with snarling lions. The party stands small in the shadow of the archway, weapons low.",
      "characters": ["map_reader", "scout", "magic_helper", "bridge_walker"]
    },
    {
      "scene_number": 4,
      "caption": "An armored patrol marches the outer street.",
      "visual_description": "From behind a fallen column, the scout peers at six rust-armored soldiers in lockstep down a cobbled avenue, pikes glinting in cold light.",
      "characters": ["scout", "armored_patrol_captain"]
    },
    {
      "scene_number": 5,
      "caption": "Frightened townspeople whisper of the prisoner.",
      "visual_description": "A huddle of ragged citizens in a candlelit cellar, one old woman pressing a key into the magic helper's palm, eyes wide with fear.",
      "characters": ["magic_helper", "frightened_elder"]
    },
    {
      "scene_number": 6,
      "caption": "The cursed tower looms over the rooftops.",
      "visual_description": "A tilted black tower wrapped in slow green flame, visible above broken chimneys. The party stares up from a narrow alley, faces lit sickly green.",
      "characters": ["map_reader", "magic_helper", "bridge_walker"]
    },
    {
      "scene_number": 7,
      "caption": "The scout warns against the tower's bait.",
      "visual_description": "Scout grabs the magic helper's sleeve, pointing at glittering treasure piled at the tower's base. Skeletal hands are just visible beneath the gold.",
      "characters": ["scout", "magic_helper"]
    },
    {
      "scene_number": 8,
      "caption": "A rumor of dragons drifts from a tavern ruin.",
      "visual_description": "Inside a half-collapsed inn, a sleepy official slumps over a tankard, gesturing wildly at a crude dragon mural on the wall. Dust motes drift in lantern light.",
      "characters": ["sleepy_official", "map_reader"]
    },
    {
      "scene_number": 9,
      "caption": "The map reader refuses the dragon detour.",
      "visual_description": "Map reader firmly folds the map shut, shaking their head at the sleepy official, who shrugs and goes back to sleep on the bar.",
      "characters": ["map_reader", "sleepy_official"]
    },
    {
      "scene_number": 10,
      "caption": "Old royal banners line the inner courtyard.",
      "visual_description": "Tattered crimson and gold banners hang in a wide courtyard of cracked tile. The party walks single file down the center, ignoring the heraldry tugging at memory.",
      "characters": ["map_reader", "scout", "magic_helper", "bridge_walker"]
    },
    {
      "scene_number": 11,
      "caption": "They reach a sealed magic door.",
      "visual_description": "A tall door of blue stone covered in glowing runes blocks a stairwell. The magic helper raises both hands, runes reflecting in their eyes.",
      "characters": ["magic_helper", "map_reader"]
    },
    {
      "scene_number": 12,
      "caption": "The door yields to a whispered name.",
      "visual_description": "The runes flare white, then fade. The stone door splits silently down the middle, revealing a dark spiral stair descending into blue mist.",
      "characters": ["magic_helper", "map_reader", "scout", "bridge_walker"]
    },
    {
      "scene_number": 13,
      "caption": "The scout disables a tripwire on the stair.",
      "visual_description": "Crouched on a narrow step, the scout slips a dagger under a taut silver wire while the others freeze behind, holding their breath.",
      "characters": ["scout", "magic_helper", "bridge_walker"]
    },
    {
      "scene_number": 14,
      "caption": "They find the captive in a vaulted cell.",
      "visual_description": "A young captive in torn fine clothes, chained at the wrist beneath a single shaft of light from a high cracked window. The party rushes forward.",
      "characters": ["captive_heir", "magic_helper", "map_reader", "scout", "bridge_walker"]
    },
    {
      "scene_number": 15,
      "caption": "The magic helper breaks the binding chain.",
      "visual_description": "Sparks burst from the iron shackle as the magic helper presses a glowing palm to it. The captive winces, then stands, free.",
      "characters": ["magic_helper", "captive_heir"]
    },
    {
      "scene_number": 16,
      "caption": "The patrol storms the courtyard above.",
      "visual_description": "Wide shot from the stair top: the armored captain points down the corridor, soldiers fanning out with torches raised. Shadows leap on the walls.",
      "characters": ["armored_patrol_captain", "scout"]
    },
    {
      "scene_number": 17,
      "caption": "They race toward the great bridge.",
      "visual_description": "The party sprints across rubble toward a long stone bridge spanning a misty chasm at the city's edge, dawn breaking gold behind it.",
      "characters": ["map_reader", "scout", "magic_helper", "bridge_walker", "captive_heir"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge walker holds the span as they escape.",
      "visual_description": "Mid-bridge, the bridge walker turns and slams a staff down; stones behind them crumble into the chasm while the others reach the far side, the captive looking back.",
      "characters": ["bridge_walker", "captive_heir", "map_reader", "scout", "magic_helper"]
    }
  ]
}

